.tier-label { overflow-wrap:anywhere; }
.tier-progress-text { display:block; margin:5px 0 3px; color:#94a3b8; font-size:11px; line-height:1.5; overflow-wrap:anywhere; }
.tier-progress { display:block; width:100%; height:5px; border:0; border-radius:3px; accent-color:#60a5fa; overflow:hidden; }
.tier-progress::-webkit-progress-bar { background:#334155; }
.tier-progress::-webkit-progress-value { background:#60a5fa; }
.tier-progress::-moz-progress-bar { background:#60a5fa; }
.tier-guide { padding:10px 16px; color:#94a3b8; font-size:12px; line-height:1.6; }
.tier-guide summary { cursor:pointer; color:#cbd5e1; }
.ranking-columns { display:grid; grid-template-columns:28px minmax(0,1fr) minmax(84px,40%); gap:8px; align-items:center; }
