.menu-tier-columns { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px; font-size:12px; }
.menu-tier-column { display:flex; flex-direction:column; gap:6px; min-width:0; overflow-wrap:anywhere; }
.menu-tier-column > :last-child { margin-top:auto; color:#94a3b8; font-size:11px; }
.main-menu-modes button { min-width:0; word-break:keep-all; overflow-wrap:anywhere; }
.main-menu-panel h1 { max-width:100%; overflow-wrap:anywhere; }
.ranking-own-tier { display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:6px; color:#cbd5e1; }
.ranking-own-detail { margin-top:6px; color:#cbd5e1; line-height:1.5; }
.ranking-modal-card .tier-guide { margin-top:8px; padding-left:0; padding-right:0; }
.ranking-retry { display:block; margin:12px auto 0; padding:10px 16px; min-height:44px; color:#f8fafc; background:#334155; border:1px solid #64748b; border-radius:6px; cursor:pointer; }
.ranking-modal-card button { min-height:40px; }
.ranking-modal-card button[aria-pressed] { min-width:0; overflow-wrap:anywhere; }
.ranking-columns > * { min-width:0; overflow-wrap:anywhere; }
.ranking-modal-card button[aria-pressed="true"] { font-weight:800; text-decoration:underline; text-underline-offset:4px; }
.ranking-modal-card button:focus-visible, .tier-guide summary:focus-visible { outline:2px solid #f8fafc; outline-offset:2px; }
@media (prefers-reduced-motion: reduce) { .ranking-modal-card button { transition:none !important; } }

* {
  box-sizing: border-box;
}

html,
body,
#app {
  width: 100%;
  height: 100%;
}

body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  overflow: hidden;
  background: #171410;
}

#app {
  position: relative;
}

.game-canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

.aim-power {
  position: absolute;
  z-index: 3;
  left: 50%;
  bottom: 2rem;
  min-width: 5rem;
  padding: 0.35rem 0.7rem;
  border-radius: 999px;
  background: rgb(12 14 17 / 78%);
  font: 700 1rem/1.2 ui-monospace, "Cascadia Mono", Consolas, monospace;
  text-align: center;
  pointer-events: none;
  transform: translateX(-50%);
}

/* 오른쪽 아래는 조준 수치판이 쓰므로 겹치지 않는 왼쪽 아래에 둔다. */
.aim-elevation {
  position: absolute;
  z-index: 3;
  left: 0.75rem;
  bottom: 0.75rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.15rem;
  padding: 0.4rem 0.5rem 0.3rem;
  border-radius: 0.6rem;
  background: rgb(12 14 17 / 78%);
  pointer-events: none;
}

/* display를 지정하면 hidden 속성이 무시되므로 숨김 규칙을 다시 준다. */
.aim-elevation[hidden] {
  display: none;
}

.aim-elevation-dial {
  width: 6rem;
  height: 6rem;
}

.aim-elevation-board {
  stroke: rgb(255 255 255 / 55%);
  stroke-width: 2.5;
}

.aim-elevation-limit {
  stroke: rgb(255 255 255 / 20%);
  stroke-width: 1.5;
  stroke-dasharray: 4 4;
}

.aim-elevation-pivot {
  fill: rgb(255 255 255 / 70%);
}

.aim-elevation-needle {
  fill: #ffd54a;
}

.aim-elevation-value {
  font: 700 0.8rem/1 ui-monospace, "Cascadia Mono", Consolas, monospace;
  color: #ffd54a;
}

.turn-hud-container {
