.main-menu-modes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.65rem;
}

.online-lobby-panel {
  position: absolute;
  z-index: 31;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 1rem;
  overflow: auto;
  background: #0f172a;
}

.online-lobby-card {
  display: grid;
  width: min(34rem, 100%);
  gap: 0.65rem;
  padding: clamp(1rem, 3vw, 1.5rem);
  border: 1px solid rgb(255 255 255 / 18%);
  border-radius: 0.9rem;
  background: rgb(24 20 16 / 98%);
  box-shadow: 0 1.25rem 4rem rgb(0 0 0 / 48%);
}

.online-lobby-card h2,
.online-lobby-card p {
  margin: 0;
}

.online-lobby-card h2 {
  color: #ffe7a3;
  text-align: center;
}

.online-lobby-card p {
  color: #d8d0c4;
  font-size: 0.82rem;
  line-height: 1.4;
  text-align: center;
}

.online-path-buttons,
.online-lobby-card section {
  display: grid;
  gap: 0.55rem;
}

.online-path-buttons {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.online-lobby-card section[hidden] {
  display: none;
}

.online-lobby-card label {
  display: grid;
  gap: 0.3rem;
  color: #d8d0c4;
  font-size: 0.78rem;
}

.online-lobby-card textarea {
  box-sizing: border-box;
  width: 100%;
  min-height: 5rem;
  padding: 0.45rem;
  resize: vertical;
  border: 1px solid rgb(255 255 255 / 18%);
  border-radius: 0.45rem;
  background: rgb(0 0 0 / 30%);
  color: #eff4f8;
  font: 0.68rem/1.35 ui-monospace, "Cascadia Mono", Consolas, monospace;
}

.main-menu-modes button,
.online-lobby-card button,
.permanent-upgrade-row button,
.permanent-upgrade-reset {
  padding: 0.6rem 0.75rem;
  border: 1px solid #ffd54a;
  border-radius: 0.5rem;
  color: #171410;
  background: #ffd54a;
  font: inherit;
  font-weight: 700;
  cursor: pointer;
}

.main-menu-modes button:disabled,
.online-lobby-card button:disabled,
.permanent-upgrade-row button:disabled,
.permanent-upgrade-reset:disabled {
  border-color: rgb(255 255 255 / 14%);
  color: #8f887f;
  background: rgb(255 255 255 / 5%);
  cursor: not-allowed;
}

.main-menu-status {
  min-height: 1.25rem;
  margin: 0.55rem 0;
  color: #ffe7a3;
  font-size: 0.78rem;
  text-align: center;
}

.main-menu-status:empty {
  display: none;
}


.permanent-upgrade-panel h2 {
  margin: 0 0 0.55rem;
  font-size: 1rem;
}

.permanent-upgrade-heading,
.permanent-upgrade-row {
  display: grid;
  grid-template-columns:
    minmax(6.5rem, 1.4fr)
    repeat(3, minmax(4.5rem, 0.8fr))
    4.5rem;
  gap: 0.4rem;
  align-items: center;
}

.permanent-upgrade-heading {
  padding: 0 0.55rem 0.35rem;
  color: #9f978d;
  font-size: 0.7rem;
}

.permanent-upgrade-row {
  margin-top: 0.3rem;
  padding: 0.4rem 0.55rem;
  border: 1px solid rgb(255 255 255 / 9%);
  border-radius: 0.45rem;
  background: rgb(255 255 255 / 3%);
  font-size: 0.76rem;
}

.permanent-upgrade-row[data-locked="true"] {
  border-color: rgb(255 255 255 / 5%);
  opacity: 0.58;
}

.permanent-upgrade-tier-title {
  margin: 0.75rem 0 0.2rem;
  color: #ffd978;
  font-size: 0.82rem;
}

.permanent-upgrade-size-row {
  margin-block: 0.8rem;
  border-color: rgb(255 213 74 / 38%);
  background: rgb(255 213 74 / 7%);
}

.permanent-upgrade-row strong {
  color: #f4e7c5;
}

.permanent-upgrade-row button {
  padding: 0.35rem 0.45rem;
  font-size: 0.74rem;
}

.permanent-upgrade-reset {
  width: 100%;
  margin-top: 0.85rem;
}

.menu-confirm-overlay {
  z-index: 40;
}


.loading-panel p,
.error-panel h1 {
  margin: 0;
}

.error-panel h1 {
  margin-bottom: 0.75rem;
  font-size: 1.1rem;
}

.error-panel pre {
  max-height: 60vh;
  margin: 0;
  overflow: auto;
  color: #ffb4a9;
  white-space: pre-wrap;
}

.debug-overlay {
  position: absolute;
  z-index: 2;
  top: 0.75rem;
  left: 0.75rem;
  min-width: 0;
  max-width: calc(100vw - 1.5rem);
  margin: 0;
  padding: 0.45rem 0.65rem;
  border: 1px solid rgb(255 255 255 / 12%);
  border-radius: 0.45rem;
  background: rgb(12 14 17 / 78%);
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 25%);
  color: #eff4f8;
  font: 0.72rem/1.2 ui-monospace, "Cascadia Mono", Consolas, monospace;
  cursor: pointer;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.debug-overlay.is-expanded {
  min-width: 20rem;
  max-height: calc(100vh - 1.5rem);
  padding: 0.7rem 0.8rem;
  overflow: auto;
  line-height: 1.42;
  text-overflow: clip;
  white-space: pre-wrap;
}

.replay-panel {
  position: absolute;
  z-index: 12;
  right: 0.75rem;
  bottom: 0.75rem;
  display: grid;
  width: min(18rem, calc(100vw - 1.5rem));
  gap: 0.45rem;
  padding: 0.7rem;
  border: 1px solid rgb(255 255 255 / 14%);
  border-radius: 0.55rem;
  background: rgb(12 14 17 / 90%);
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 30%);
  color: #eff4f8;
}

.replay-panel h2,
.replay-panel p {
  margin: 0;
}

.replay-panel h2 {
  color: #f4e7c5;
  font-size: 0.9rem;
}

.replay-panel p {
  color: #cbd5df;
  font-size: 0.72rem;
  line-height: 1.35;
}

.net-panel {
  position: absolute;
  z-index: 13;
  bottom: 0.75rem;
  left: 0.75rem;
  display: grid;
  width: min(24rem, calc(100vw - 1.5rem));
  max-height: calc(100vh - 1.5rem);
  gap: 0.45rem;
  padding: 0.7rem;
  overflow: auto;
  border: 1px solid rgb(255 255 255 / 14%);
  border-radius: 0.55rem;
  background: rgb(12 14 17 / 92%);
  box-shadow: 0 0.5rem 1.5rem rgb(0 0 0 / 30%);
  color: #eff4f8;
}

.net-panel h2,
.net-panel p {
  margin: 0;
}

.net-panel h2 {
  color: #f4e7c5;
  font-size: 0.9rem;
}

.net-panel p,
.net-panel label {
  color: #cbd5df;
  font-size: 0.72rem;
  line-height: 1.35;
}

.net-code-row,
.net-code-row label {
  display: grid;
  gap: 0.3rem;
}

.net-panel textarea,
.net-panel input {
  box-sizing: border-box;
  width: 100%;
  border: 1px solid rgb(255 255 255 / 18%);
  border-radius: 0.35rem;
  background: rgb(0 0 0 / 32%);
  color: #eff4f8;
  font: 0.68rem/1.35 ui-monospace, "Cascadia Mono", Consolas, monospace;
}

.net-panel textarea {
  min-height: 3.4rem;
  padding: 0.35rem;
  resize: vertical;
}

.net-panel input {
  min-width: 0;
  padding: 0.45rem;
}

.net-message-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.35rem;
}

.net-log {
  min-height: 3.5rem;
  max-height: 8rem;
  margin: 0;
  padding: 0.4rem;
  overflow: auto;
  border-radius: 0.35rem;
  background: rgb(0 0 0 / 28%);
  color: #d8e0e8;
  font: 0.66rem/1.35 ui-monospace, "Cascadia Mono", Consolas, monospace;
  white-space: pre-wrap;
}

@media (max-width: 600px) {
  /* 상단 중앙: 턴 정보 & 타이머 HUD (충분한 좌우 공간 확보로 겹침 0%) */
  .turn-hud-container {
    top: 8px;
    left: 50%;
    transform: translateX(-50%);
    height: 28px;
    z-index: 15;
  }

  .turn-hud-badge {
    padding: 0 8px !important;
    gap: 5px !important;
    height: 28px !important;
    border-radius: 6px !important;
    background: rgba(15, 23, 42, 0.94) !important;
    backdrop-filter: blur(4px);
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4) !important;
    box-sizing: border-box;
  }

  .turn-hud-side {
    font-size: 11px !important;
    gap: 4px !important;
  }

  .turn-hud-timer-text {
    font-size: 12px !important;
    min-width: 28px !important;
  }

  .turn-hud-progress-track {
    width: 28px !important;
    height: 4px !important;
  }

  /* 상단 좌측: 당구식 / 클래식 조작 모드 토글 */
  .input-mode-toggle {
    top: 8px;
    left: 8px;
    right: auto;
    transform: none;
    padding: 2px;
    gap: 2px;
    border-radius: 6px;
    background: rgba(15, 23, 42, 0.88);
    backdrop-filter: blur(4px);
    z-index: 20;
    height: 28px;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .input-mode-toggle button {
    padding: 0 6px;
    font-size: 11px;
    font-weight: 700;
    border-radius: 4px;
    height: 24px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
    font-family: inherit;
    box-sizing: border-box;
    margin: 0;
  }

  /* 상단 우측 1단: 메뉴로 버튼 (우측 상단 끝) */
  .return-menu-button {
    top: 8px;
    right: 8px;
    left: auto;
    width: 54px;
    min-width: 54px;
    height: 28px;
    padding: 0;
    font-size: 11px;
    font-weight: 700;
    border-radius: 6px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    z-index: 20;
  }

  /* 상단 우측 2단 (메뉴 버튼 바로 아래 세로 배치): Ping HUD 뱃지 */
  .online-ping-hud {
    top: 40px;
    right: 8px;
    width: 54px;
    min-width: 54px;
    height: 24px;
    padding: 0;
    font-size: 10px;
    font-weight: 700;
    border-radius: 6px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 3px;
    box-sizing: border-box;
    z-index: 25;
  }

  .debug-overlay {
    top: 2.8rem;
    left: 0.4rem;
    width: auto;
    max-width: calc(100vw - 0.8rem);
    padding: 0.35rem 0.5rem;
    font: 0.62rem/1.2 ui-monospace, "Cascadia Mono", Consolas, monospace;
  }

  .debug-overlay.is-expanded {
    top: 3.5rem;
    width: auto;
    max-width: calc(100vw - 0.8rem);
    max-height: calc(100vh - 3.9rem);
    padding: 0.5rem;
    line-height: 1.42;
  }

  .strike-point-panel {
    left: 0.4rem;
  }

  .aim-parameters,
  .tuning-panel {
    right: 0.4rem;
    left: auto;
    width: calc(100vw - 0.8rem);
  }

  .aim-parameters {
    bottom: 0.4rem;
    width: auto;
    padding: 0.45rem;
  }

  .aim-parameters .strike-feedback {
    margin: 0;
    font-size: 0.64rem;
    line-height: 1.25;
  }

  .aim-parameters .aim-error {
    margin: 0;
    font-size: 0.62rem;
    line-height: 1.25;
  }

  .tuning-panel {
    top: 3.7rem;
    max-height: calc(100vh - 4.1rem);
  }

  .card-tuning-panel {
    right: 0.4rem;
    left: auto;
  }

  .tuning-control {
    grid-template-columns: 4.8rem minmax(4rem, 1fr) 3.4rem 4rem;
    gap: 0.25rem;
  }

  .main-menu-overlay {
    padding: 0.4rem;
  }

  .replay-panel {
    right: 0.4rem;
    bottom: 0.4rem;
    width: min(15rem, calc(100vw - 0.8rem));
    padding: 0.55rem;
  }

  .net-panel {
    bottom: 0.4rem;
    left: 0.4rem;
    width: calc(100vw - 0.8rem);
    max-height: calc(100vh - 0.8rem);
    padding: 0.55rem;
  }

  .main-menu-panel {
    max-height: calc(100vh - 0.8rem);
    padding: 0.8rem;
  }

  .permanent-upgrade-heading {
    display: none;
  }

  .permanent-upgrade-row {
    grid-template-columns: minmax(6rem, 1.2fr) repeat(3, 1fr) 3.6rem;
    gap: 0.25rem;
    padding: 0.35rem;
    font-size: 0.66rem;
  }

  .permanent-upgrade-row button {
    min-width: 0;
    padding: 0.3rem 0.2rem;
    font-size: 0.66rem;
  }
}

/* ==========================================================================
   광고 배너 (AdSense / AdMob) 레이아웃 및 Mock 스타일
   ========================================================================== */

.ad-container {
  z-index: 15;
  box-sizing: border-box;
  user-select: none;
}

/* PC 좌우 사이드바 배너 (160x600) */
.pc-side-ad {
  position: fixed;
  top: 50%;
  transform: translateY(-50%);
  width: 160px;
  height: 600px;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
}

.ad-container {
  z-index: 40;
  box-sizing: border-box;
  user-select: none;
}

/* PC 좌우 사이드바 배너 (160x600) */
.pc-side-ad {
  position: fixed;
  top: 50%;
  transform: translateY(-50%);
  width: 160px;
  height: 600px;
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: auto;
}

.pc-side-ad.left-ad {
  left: 12px;
}

.pc-side-ad.right-ad {
  right: 12px;
}

/* 모바일 전용 하단 배너 (Adaptive Banner 50px) */
.mobile-ad-bottom {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  height: 50px;
  z-index: 50;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(15, 23, 42, 0.96);
  border-top: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow: 0 -4px 15px rgba(0, 0, 0, 0.5);
  pointer-events: auto;
}

/* 개발/테스트 모드용 Mock UI */
