/* ==========================================================================
   인터랙티브 튜토리얼 UI 스타일
   ========================================================================== */

.tutorial-coach-overlay {
  position: fixed;
  top: var(--tutorial-coach-top, 4.8rem);
  left: 50%;
  transform: translateX(-50%);
  z-index: 25;
  pointer-events: none;
  width: min(92vw, 480px);
  user-select: none;
  animation: tutorialFadeIn 0.3s ease-out;
}

@keyframes tutorialFadeIn {
  from {
    opacity: 0;
    transform: translate(-50%, -10px);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

.tutorial-coach-card {
  background: #0f172a;
  border: 1px solid #3b82f6;
  border-radius: 10px;
  padding: 10px 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.4);
  text-align: center;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

.tutorial-coach-header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-bottom: 6px;
}

.tutorial-step-badge {
  color: #94a3b8;
  font-size: 11px;
  font-weight: 700;
  padding: 2px 0;
  border-radius: 4px;
  letter-spacing: 0.05em;
}

.tutorial-step-title {
  color: #f8fafc;
  font-size: 14px;
  font-weight: 700;
}

.tutorial-mission-text {
  color: #e2e8f0;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 4px;
  line-height: 1.4;
}

.tutorial-guide-text {
  color: #93c5fd;
  font-size: 12px;
  line-height: 1.35;
}

/* 튜토리얼 팝업 모달 */
.tutorial-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(11, 15, 25, 0.92);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  animation: tutorialModalPop 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes tutorialModalPop {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.tutorial-modal-card {
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 16px;
  padding: 28px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6);
  box-sizing: border-box;
  max-height: 100%;
  overflow-y: auto;
}

body[data-tutorial="basic"] .input-mode-toggle { display: none; }
body[data-tutorial] #app {
  --game-board-top: calc(var(--tutorial-coach-top, 4.8rem) + var(--tutorial-coach-height, 140px) + 8px);
}
body[data-tutorial="basic"] #app {
  --game-hud-height: calc(150px + env(safe-area-inset-bottom, 0px));
  --game-dock-bottom: calc(52px + env(safe-area-inset-bottom, 0px));
}
body[data-tutorial="basic"] #app .aim-power { bottom: calc(8px + env(safe-area-inset-bottom, 0px)); }
.ui-motion-reduced .tutorial-coach-overlay,
.ui-motion-reduced .tutorial-modal-overlay { animation: none; }
.tutorial-more-button { background: transparent; color: #cbd5e1; border: 0; min-height: 44px; padding: 10px; font: inherit; cursor: pointer; }
.tutorial-modal-card button:focus-visible { outline: 2px solid #93c5fd; outline-offset: 3px; }
.tutorial-coach-header { flex-wrap: wrap; }
.tutorial-skip-button {
  margin-left: auto;
  padding: 5px 9px;
  min-height: 32px;
  border: 1px solid #64748b;
  border-radius: 5px;
  background: transparent;
  color: #e2e8f0;
  font: inherit;
  font-size: 12px;
  cursor: pointer;
  pointer-events: auto;
}
.tutorial-skip-button:focus-visible { outline: 2px solid #93c5fd; outline-offset: 2px; }
@media (pointer: coarse) { .tutorial-skip-button { min-height: 44px; } }
.tutorial-guide-text:empty { display: none; }
@media (max-height: 500px) {
  body[data-tutorial] { --tutorial-coach-top: 48px; }
