/* ==========================================================================
   폰 프로모션(승급) 모달 스타일
   ========================================================================== */

.promotion-modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(11, 15, 25, 0.92);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  animation: promotionModalIn 0.2s ease-out;
}

.promotion-modal-overlay.promotion-closing {
  animation: promotionModalOut 0.12s ease-in forwards;
}

@keyframes promotionModalIn {
  from {
    opacity: 0;
    transform: scale(0.96);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes promotionModalOut {
  from {
    opacity: 1;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(0.98);
  }
}

.promotion-modal-card {
  width: 100%;
  max-width: 460px;
  max-height: 88vh;
  overflow-y: auto;
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 14px;
  padding: 22px 18px;
  box-shadow: 0 20px 40px -10px rgba(0, 0, 0, 0.6);
  box-sizing: border-box;
  color: #f8fafc;
  display: flex;
  flex-direction: column;
  gap: 14px;
  text-align: center;
}

.promotion-modal-header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.promotion-title {
  margin: 0;
  font-size: 19px;
  font-weight: 700;
  color: #f8fafc;
}

.promotion-subtitle {
  margin: 0;
  font-size: 13px;
  color: #94a3b8;
  line-height: 1.4;
}

.promotion-piece-grid {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.promotion-piece-card {
  display: flex;
  align-items: center;
  gap: 14px;
  background: #0f172a;
  border: 1px solid #334155;
  border-radius: 10px;
  padding: 10px 14px;
  cursor: pointer;
  text-align: left;
  transition: background-color 0.15s ease, border-color 0.15s ease;
  color: #f8fafc;
}

.promotion-piece-card:hover {
  background: #1e293b;
  border-color: #38bdf8;
}

.promotion-piece-card:active {
  background: #162032;
}

.promotion-piece-symbol {
  font-size: 26px;
  line-height: 1;
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 8px;
}

.promotion-piece-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.promotion-piece-name {
  font-size: 14px;
  font-weight: 700;
  color: #f8fafc;
}

.promotion-piece-desc {
  font-size: 12px;
  color: #94a3b8;
  line-height: 1.35;
}

/* ==========================================================================
   킹 위치 교환(스왑) 안내 배너 스타일
   ========================================================================== */

.king-swap-banner {
  position: absolute;
  top: auto;
  background: #1e293b;
  border: 1px solid #475569;
  border-radius: 9999px;
  padding: 8px 20px;
  font-size: 13px;
  font-weight: 600;
  color: #f8fafc;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.45);
  z-index: 100;
  pointer-events: none;
  width: max-content;
  max-width: calc(100% - 24px);
  box-sizing: border-box;
  white-space: normal;
  overflow-wrap: anywhere;
  text-align: center;
  line-height: 1.35;
  animation: kingSwapBannerIn 0.15s ease-out;
}

@keyframes kingSwapBannerIn {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.strike-action-bar button[data-action="defend"] {
  border-color: #38bdf8;
  color: #38bdf8;
}

.site-menu-links {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  margin-top: 14px;
  font-size: 12px;
}
.site-menu-links a { color: #cbd5e1; padding: 6px 0; }
.site-menu-links a:focus-visible { outline: 2px solid #ffe7a3; outline-offset: 3px; }

.strike-action-bar button[data-action="defend"]:hover {
  background: rgba(56, 189, 248, 0.18);
}




/* Give the turn label its own row on narrow phones. */
@media (max-width:520px) and (orientation:portrait) {
  .turn-hud-container { top:50px; }
  body[data-tutorial] { --tutorial-coach-top: 88px; }
  body[data-tutorial] .turn-hud-side { white-space: nowrap; }
}

/* Result controls and motion accessibility. */
.match-result-panel button { min-height: 44px; overflow-wrap: anywhere; }
.match-result-panel button:focus-visible { outline: 2px solid #fff0bc; outline-offset: 3px; }
.match-result-panel button:active:not(:disabled) { transform: translateY(1px); filter: brightness(.9); }
.match-result-panel .match-action-status { color: #ffd7a3; margin: .75rem 0; line-height: 1.5; }
.match-action-status[hidden] { display: none; }
@media (prefers-reduced-motion: reduce) {
  .turn-hud-timer-text { animation: none !important; }
  .turn-hud-progress-track > * { transition: none !important; }
}

import { createRequire } from 'node:module';
import { pathToFileURL } from 'node:url';
import path from 'node:path';
import { restrictedContext } from './browser-policy.mjs';
const require = createRequire(import.meta.url);

// Executes the supplied real module in a local component scene, not a full match.
export async function withScene(web, options, inspect) {
  const gameRequire=createRequire(path.join(web,'package.json'));
  const {createServer}=await import(pathToFileURL(gameRequire.resolve('vite')).href);
  const {chromium}=require('playwright');
  const server=await createServer({root:web,configFile:false,appType:'custom',
    optimizeDeps:{noDiscovery:true,entries:[]},cacheDir:path.join(web,'../work/vite-cache'),logLevel:'error',
    server:{host:'127.0.0.1',port:0,hmr:false,fs:{allow:[web,path.dirname(gameRequire.resolve('vite'))]}},
    define:{__POKI_BUILD__:'false',__CRAZYGAMES_BUILD__:'false',__PORTABLE_BUILD__:'false'}});
  server.middlewares.use('/scene',(req,res)=>{
    res.setHeader('Content-Type','text/html');
    res.end(`<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/src/style.css"><div id="app"><button id="open">Open promotion</button></div>
      <script type="module">
      import {openPromotionModal,PROMOTION_PIECE_OPTIONS} from '/src/promotion-modal.ts';
      import {I18nManager} from '/src/i18n.ts';
      import {setMotionReduced} from '/src/ui-motion.ts';
      window.__case={calls:[],options:PROMOTION_PIECE_OPTIONS,language:I18nManager,motion:setMotionReduced,
        open(owner='current',side='white'){openPromotionModal('white-pawn-a7',side,type=>__case.calls.push({owner,type}),document.querySelector('#app'));}};
      document.querySelector('#open').onclick=()=>__case.open();window.ready=true;
      </script>`);
  });
  let browser;
  try {
    await server.listen();
    const origin=`http://127.0.0.1:${server.httpServer.address().port}`;
    browser=await chromium.launch({headless:true,...(process.env.BROWSER_PATH?{executablePath:process.env.BROWSER_PATH}:{})});
    const {context,policy}=await restrictedContext(browser,origin,{viewport:{width:360,height:800},...options});
    const page=await context.newPage();page.setDefaultTimeout(5000);
    const errors=[];page.on('pageerror',()=>errors.push('pageerror'));
    await page.goto(origin+'/scene');await page.waitForFunction(()=>window.ready);
    return await inspect({page,context,origin,policy,errors,browserVersion:browser.version()});
  } finally {try{await browser?.close();}finally{await server.close();}}
}

